//! `ExecutorchInference` end-to-end against the real ExecuTorch runtime.
//!
//! The fixture is a checked-in `.pte` program computing `x * SCALE + OFFSET`
//! (generated by `tests/fixtures/export_affine.py`, whose constants these mirror).
//!
//! Run with:
//!
//! ```powershell
//! cargo test -p g2g-ml --features executorch,analytics,launch --test executorch_inference
//! ```

#![cfg(feature = "executorch")]

use g2g_core::element::{AsyncElement, OutputSink, PushOutcome};
use g2g_core::frame::{Frame, FrameTiming, PipelinePacket};
use g2g_core::memory::{MemoryDomain, SystemSlice};
use g2g_core::{Caps, Dim, G2gError, Rate, RawVideoFormat, TensorDType, TensorLayout, TensorShape};
use g2g_ml::executorchinfer::ExecutorchInference;

const MODEL_PATH: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/affine_2x_plus_1.pte"
);
// the constants `export_affine.py` exported the fixture with
const SCALE: f32 = 2.0;
const OFFSET: f32 = 1.0;
const SHAPE: [u32; 4] = [1, 3, 4, 4];

const CHANNELS: usize = SHAPE[1] as usize;
const HEIGHT: u32 = SHAPE[2];
const WIDTH: u32 = SHAPE[3];
const PLANE: usize = (WIDTH * HEIGHT) as usize;
const RGBA_BYTES_PER_PIXEL: usize = 4;
const U8_FULL_SCALE: f32 = 255.0;

#[derive(Default)]
struct Collect {
    packets: Vec<PipelinePacket>,
}

impl OutputSink for Collect {
    fn poll_push(
        &mut self,
        _cx: &mut core::task::Context<'_>,
        packet_slot: &mut Option<PipelinePacket>,
    ) -> core::task::Poll<Result<PushOutcome, G2gError>> {
        let packet = packet_slot.take().expect("poll_push without a packet");
        self.packets.push(packet);
        core::task::Poll::Ready(Ok(PushOutcome::Accepted))
    }
}

fn rgba_caps(width: u32, height: u32) -> Caps {
    Caps::RawVideo {
        format: RawVideoFormat::Rgba8,
        width: Dim::Fixed(width),
        height: Dim::Fixed(height),
        framerate: Rate::Any,
        interlace: g2g_core::Interlace::Any,
        colorimetry: g2g_core::Colorimetry::UNKNOWN,
    }
}

fn output_caps() -> Caps {
    Caps::Tensor {
        dtype: TensorDType::F32,
        shape: TensorShape::new(SHAPE),
        layout: TensorLayout::Nchw,
    }
}

fn system_frame(bytes: Vec<u8>) -> Frame {
    Frame {
        domain: MemoryDomain::System(SystemSlice::from_boxed(bytes.into_boxed_slice())),
        timing: FrameTiming::default(),
        sequence: 0,
        meta: Default::default(),
    }
}

fn f32_values(frame: &Frame) -> Vec<f32> {
    let slice = frame
        .domain
        .as_system_slice()
        .expect("tensor frames are System-domain");
    slice
        .as_chunks::<4>()
        .0
        .iter()
        .map(|chunk| f32::from_le_bytes(*chunk))
        .collect()
}

fn affine(value: f32) -> f32 {
    value * SCALE + OFFSET
}

#[test]
fn model_geometry_is_read_from_the_program() {
    let element = ExecutorchInference::from_file(MODEL_PATH).expect("fixture loads");
    assert_eq!(element.input_dims(), (WIDTH, HEIGHT));
    assert_eq!(element.output_shape(), &SHAPE);
}

#[tokio::test]
async fn rgba_frame_runs_through_the_program() {
    let mut element = ExecutorchInference::from_file(MODEL_PATH).expect("fixture loads");
    assert_eq!(
        element.intercept_caps(&rgba_caps(WIDTH * 2, HEIGHT)),
        Err(G2gError::CapsMismatch),
        "geometry is pinned to the model input"
    );
    element
        .configure_pipeline(&rgba_caps(WIDTH, HEIGHT))
        .expect("configure");

    // every byte distinct, so a swapped channel or pixel changes the output
    let rgba: Vec<u8> = (0..(PLANE * RGBA_BYTES_PER_PIXEL) as u8).collect();
    let mut sink = Collect::default();
    element
        .process(
            PipelinePacket::DataFrame(system_frame(rgba.clone())),
            &mut sink,
        )
        .await
        .expect("frame");

    let [PipelinePacket::CapsChanged(caps), PipelinePacket::DataFrame(frame)] = &sink.packets[..]
    else {
        panic!("expected CapsChanged then one tensor frame");
    };
    assert_eq!(caps, &output_caps());

    let mut expected = Vec::with_capacity(CHANNELS * PLANE);
    for channel in 0..CHANNELS {
        for pixel in 0..PLANE {
            let byte = rgba[pixel * RGBA_BYTES_PER_PIXEL + channel];
            expected.push(affine(f32::from(byte) / U8_FULL_SCALE));
        }
    }
    assert_eq!(f32_values(frame), expected);
    assert_eq!(element.inferred_count(), 1);
}

#[tokio::test]
async fn tensor_input_feeds_the_program_directly() {
    let mut element = ExecutorchInference::from_file(MODEL_PATH)
        .expect("fixture loads")
        .with_tensor_input();
    let tensor_caps = Caps::Tensor {
        dtype: TensorDType::F32,
        shape: TensorShape::new(SHAPE),
        layout: TensorLayout::Nchw,
    };
    assert_eq!(
        element.intercept_caps(&rgba_caps(WIDTH, HEIGHT)),
        Err(G2gError::CapsMismatch)
    );
    element.configure_pipeline(&tensor_caps).expect("configure");

    let input: Vec<f32> = (0..CHANNELS * PLANE).map(|i| i as f32 - 7.5).collect();
    let bytes: Vec<u8> = input.iter().flat_map(|v| v.to_le_bytes()).collect();
    let mut sink = Collect::default();
    element
        .process(PipelinePacket::DataFrame(system_frame(bytes)), &mut sink)
        .await
        .expect("tensor frame");

    let frame = sink
        .packets
        .iter()
        .find_map(|p| match p {
            PipelinePacket::DataFrame(f) => Some(f),
            _ => None,
        })
        .expect("one tensor frame");
    let expected: Vec<f32> = input.iter().map(|v| affine(*v)).collect();
    assert_eq!(f32_values(frame), expected);
}

#[test]
fn a_missing_or_malformed_program_fails_to_load() {
    assert!(ExecutorchInference::from_file("/nonexistent/model.pte").is_err());

    let junk = std::env::temp_dir().join("g2g_executorch_junk.pte");
    std::fs::write(&junk, b"not an executorch program").expect("write junk file");
    assert!(ExecutorchInference::from_file(junk.to_str().unwrap()).is_err());

    let mut element = ExecutorchInference::new();
    assert_eq!(
        element.configure_pipeline(&rgba_caps(WIDTH, HEIGHT)).err(),
        Some(G2gError::NotConfigured)
    );
}

#[cfg(feature = "launch")]
#[test]
fn register_makes_executorchinfer_constructible() {
    use g2g_core::runtime::Registry;
    use g2g_core::PropValue;

    let mut registry = Registry::new();
    g2g_ml::register(&mut registry);
    let mut element = registry
        .make_element("executorchinfer")
        .expect("executorchinfer builds bare");
    element
        .set_property("model", PropValue::Str(MODEL_PATH.into()))
        .expect("the model property loads the program");
    assert_eq!(
        element.get_property("model"),
        Some(PropValue::Str(MODEL_PATH.into()))
    );
    assert_eq!(element.get_property("execution-provider"), None);
}
